import{_ as a,I as n,c as o,o as i,ag as t,J as s}from"./chunks/framework.Vyheyqg9.js";const g=JSON.parse('{"title":"Frontend performance: from a slow journey to evidence","description":"","frontmatter":{},"headers":[],"relativePath":"frontend/performance/index.md","filePath":"frontend/performance/index.md"}'),d={name:"frontend/performance/index.md"};function c(l,e,p,h,f,m){const r=n("MermaidDiagram");return i(),o("div",null,[e[0]||(e[0]=t('<h1 id="frontend-performance-from-a-slow-journey-to-evidence" tabindex="-1">Frontend performance: from a slow journey to evidence <a class="header-anchor" href="#frontend-performance-from-a-slow-journey-to-evidence" aria-label="Permalink to “Frontend performance: from a slow journey to evidence”">​</a></h1><p>Performance is part of a usable frontend: useful content arrives promptly, interactions respond, and the page stays stable while it loads and updates. A smaller bundle is useful only when the resulting experience and delivery cost justify the change.</p><p><strong>Prerequisites:</strong> <a href="./../html-browser.html">HTML/browser behavior</a>, CSS layout, JavaScript tasks and async ownership. Complete the browser stages before framework-specific profiling; React and Next sections require their respective foundations. <strong>All learner homework remains outstanding.</strong> Material merged with the supplied EPAM Web Performance path on <strong>2026-10-28</strong>; see <a href="./sources.html">source mapping and corrections</a>.</p><h2 id="reading-and-practice-order" tabindex="-1"><span class="hub-section-number">1 </span>Reading and practice order <a class="header-anchor" href="#reading-and-practice-order" aria-label="Permalink to “1 Reading and practice order”">​</a></h2><table tabindex="0"><thead><tr><th>Stage</th><th>Read</th><th>What you should be able to explain</th></tr></thead><tbody><tr><td>1</td><td><a href="./measurement.html">Metrics and investigation</a></td><td>Distinguish loading, responsiveness, stability and task completion; record a reproducible baseline</td></tr><tr><td>2</td><td><a href="./delivery.html">Browser loading, scripts and bundles</a></td><td>Trace discovery and execution dependencies; choose hints and split points</td></tr><tr><td>3</td><td><a href="./images.html">Responsive images</a></td><td>Deliver an appropriate candidate without delaying the hero or shifting content</td></tr><tr><td>4</td><td><a href="./css-fonts.html">Critical CSS and fonts</a></td><td>Keep content styled and readable while controlling discovery and swap costs</td></tr><tr><td>5</td><td><a href="./runtime.html">Runtime responsiveness</a></td><td>Separate CPU, rendering and network waits; choose scheduling, workers or fewer DOM nodes</td></tr><tr><td>6</td><td><a href="./caching.html">Caching and repeat visits</a></td><td>Define freshness, private/public scope, version compatibility and offline behavior</td></tr><tr><td>7</td><td><a href="./../../practice/frontend/performance/">Hometasks</a></td><td>Investigate, improve and verify the same application</td></tr></tbody></table><p>Use the course catalogue from <a href="./../../practice/frontend/">frontend practice</a>. Initial navigation, searching a large catalogue and opening course detail are different journeys with different critical dependencies. A fast landing-page audit says little about editing a long form after ten minutes of use.</p>',6)),s(r,{"encoded-source":"flowchart%20LR%0A%20%20A%5BDefine%20a%20user%20journey%5D%20--%3E%20B%5BRecord%20comparable%20baselines%5D%0A%20%20B%20--%3E%20C%5BIdentify%20the%20limiting%20dependency%5D%0A%20%20C%20--%3E%20D%5BChange%20one%20cause%5D%0A%20%20D%20--%3E%20E%5BMeasure%20and%20check%20behavior%5D%0A%20%20E%20--%3E%20F%7BWorth%20keeping%3F%7D%0A%20%20F%20--%3E%7CYes%7C%20G%5BSet%20budgets%20and%20monitor%5D%0A%20%20F%20--%3E%7CNo%7C%20C"}),e[1]||(e[1]=t('<p>For example, a late hero request suggests a discovery problem; an early hero request followed by a long gap before paint suggests other work is delaying display. Compressing an already-small hero may not fix the second case. Read the trace before choosing an optimization.</p><h2 id="existing-reference-owners" tabindex="-1"><span class="hub-section-number">2 </span>Existing reference owners <a class="header-anchor" href="#existing-reference-owners" aria-label="Permalink to “2 Existing reference owners”">​</a></h2><p>The <a href="./../../engineering/performance.html">engineering performance guide</a> remains the cross-topic investigation entry. The <a href="./../../senior_growth/Web_Performance/">senior-growth catalogue</a> retains deeper worked references for URL-to-pixels, script categories, module graphs, debounce, layout, animation, retention and SSR. This sequence integrates those references with the supplied course rather than duplicating every interview page.</p><p>Continue to <a href="./../react.html#performance-follows-correctness">React performance</a> for component identity and profiling, and <a href="./../next.html">Next delivery</a> for server/client and cache boundaries. A React render is not a browser paint; SSR can expose content earlier while hydration still consumes client CPU. Keep server diagnostics with <a href="./../../node-js/module-11-performance-diagnostics.html">Node performance</a>.</p><h2 id="what-counts-as-completion" tabindex="-1"><span class="hub-section-number">3 </span>What counts as completion <a class="header-anchor" href="#what-counts-as-completion" aria-label="Permalink to “3 What counts as completion”">​</a></h2><p>Required practice consists of <a href="./../../practice/frontend/performance/">three hometasks</a>: investigation, one loading plus one interaction improvement, and regression prevention. Each produces a before → hypothesis → change → evidence → trade-off report. Optional Webpack, browser compatibility, critical-CSS automation and service-worker exercises deepen a demonstrated need.</p><p>A build passing establishes documentation or code validity at that boundary. It does not establish learner mastery, field Web Vitals, real-device performance or a successful production rollout. No numeric improvement in these lessons is a measured result unless explicitly recorded as such.</p>',7))])}const b=a(d,[["render",c]]);export{g as __pageData,b as default};
